INSERT INTO `ieps_inform` (`id`, `head`, `publisher`, `role_id`, `subject`, `content`, `files`, `pubdate`) VALUES (400012, '关于结题验收的安排（第1期）', '104007', 200006, '外国语学院', '<p>请各项目组做好结题准备，按时提交结题报告、成果材料及经费决算表。</p><p>请相关角色按照系统时间节点完成申报、评审、过程检查与材料归档工作。</p>', NULL, '2025-06-05 00:00:00');
